import React, { useEffect, useRef, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { supabase } from "../../supabaseClient";
import { useAuth } from "../../context/AuthContext";

export default function MarkAttendance() {
  const { teacher }  = useAuth();
  const location     = useLocation();
  const navigate     = useNavigate();
  const state        = location.state;

  // If navigated without state, redirect back
  useEffect(() => {
    if (!state?.subjectId) navigate("/teacher", { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const {
    timetableId, subjectId, subjectName,
    divisionId, divisionName, className,
    startTime, endTime,
    sessionId: initialSessionId,
    isLocked: initialLocked,
  } = state || {};

  const todayDate = new Date().toISOString().split("T")[0];

  const [students, setStudents]     = useState([]);  // { id, roll_number, name, status }
  const [sessionId, setSessionId]   = useState(initialSessionId);
  const [isLocked, setIsLocked]     = useState(initialLocked || false);
  const [isEditing, setIsEditing]   = useState(false);
  const [loading, setLoading]       = useState(true);
  const [saving, setSaving]         = useState(false);
  const [locking, setLocking]       = useState(false);
  const [message, setMessage]       = useState("");
  const [error, setError]           = useState("");

  // Camera / face recognition
  const videoRef    = useRef(null);
  const [camOn, setCamOn]           = useState(false);
  const [camError, setCamError]     = useState("");

  useEffect(() => {
    if (state?.subjectId) fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function fetchData() {
    setLoading(true);
    // 1. Get enrolled students
    const { data: enrollments } = await supabase
      .from("student_enrollments")
      .select("students(id, roll_number, name, face_embedding)")
      .eq("division_id", divisionId);

    const studs = (enrollments || []).map(e => e.students).filter(Boolean);
    studs.sort((a, b) => Number(a.roll_number) - Number(b.roll_number) || a.name.localeCompare(b.name));

    // 2. If session exists, load existing records
    let existingSession = sessionId;
    if (!existingSession) {
      const { data: sess } = await supabase
        .from("attendance_sessions")
        .select("id, is_locked")
        .eq("teacher_id", teacher.id)
        .eq("subject_id", subjectId)
        .eq("division_id", divisionId)
        .eq("date", todayDate)
        .maybeSingle();
      if (sess) {
        existingSession = sess.id;
        setSessionId(sess.id);
        setIsLocked(sess.is_locked);
      }
    }

    if (existingSession) {
      const { data: records } = await supabase
        .from("attendance_records")
        .select("student_id, status")
        .eq("session_id", existingSession);

      const recMap = {};
      (records || []).forEach(r => { recMap[r.student_id] = r.status; });
      setStudents(studs.map(s => ({ ...s, status: recMap[s.id] || "absent" })));
    } else {
      // Default all present
      setStudents(studs.map(s => ({ ...s, status: "present" })));
    }

    setLoading(false);
  }

  function toggleStatus(id) {
    if (isLocked && !isEditing) return;
    setStudents(prev => prev.map(s =>
      s.id === id
        ? { ...s, status: s.status === "present" ? "absent" : "present" }
        : s
    ));
  }

  function markAll(status) {
    if (isLocked && !isEditing) return;
    setStudents(prev => prev.map(s => ({ ...s, status })));
  }

  async function handleSave() {
    setSaving(true); setError(""); setMessage("");
    try {
      let sid = sessionId;

      if (!sid) {
        // Create session
        const { data: sess, error: sessErr } = await supabase
          .from("attendance_sessions")
          .insert({
            timetable_id: timetableId || null,
            teacher_id:   teacher.id,
            subject_id:   subjectId,
            division_id:  divisionId,
            date:         todayDate,
            start_time:   startTime || null,
            end_time:     endTime || null,
          })
          .select()
          .single();
        if (sessErr) throw sessErr;
        sid = sess.id;
        setSessionId(sid);
      }

      // Upsert records
      const records = students.map(s => ({
        session_id:  sid,
        student_id:  s.id,
        status:      s.status,
        marked_by:   "manual",
      }));

      const { error: recErr } = await supabase
        .from("attendance_records")
        .upsert(records, { onConflict: "session_id,student_id" });
      if (recErr) throw recErr;

      setMessage("✅ Attendance saved successfully.");
      setIsEditing(false);
    } catch (err) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  }

  async function handleLock() {
    if (!sessionId) { setError("Save attendance before locking."); return; }
    if (!window.confirm("Lock this attendance? You can still edit it later.")) return;
    setLocking(true); setError("");
    const { error: err } = await supabase
      .from("attendance_sessions")
      .update({ is_locked: true, locked_at: new Date().toISOString() })
      .eq("id", sessionId);
    setLocking(false);
    if (err) { setError(err.message); return; }
    setIsLocked(true);
    setMessage("🔒 Attendance locked.");
  }

  async function handleUnlockForEdit() {
    setIsEditing(true);
    setMessage("✏️ Editing mode — make changes and save.");
  }

  // ── Camera ──
  async function startCamera() {
    setCamError("");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
      setCamOn(true);
    } catch (err) {
      setCamError("Camera access denied or not available. Use manual attendance.");
    }
  }

  function stopCamera() {
    if (videoRef.current?.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(t => t.stop());
    }
    setCamOn(false);
  }

  const present = students.filter(s => s.status === "present").length;
  const absent  = students.filter(s => s.status === "absent").length;

  if (loading) return <div className="page-loading">Loading students…</div>;

  const canEdit = !isLocked || isEditing;

  return (
    <div className="section">
      {/* Header info */}
      <div className="attendance-header">
        <div>
          <h2>{subjectName}</h2>
          <p style={{ color: "#555" }}>
            {className} – Div {divisionName} &nbsp;|&nbsp;
            {startTime?.slice(0,5)} – {endTime?.slice(0,5)} &nbsp;|&nbsp;
            {todayDate}
          </p>
        </div>
        <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
          {isLocked && !isEditing && (
            <span className="badge-locked">🔒 Locked</span>
          )}
          {isEditing && (
            <span className="badge-editing">✏️ Editing</span>
          )}
        </div>
      </div>

      {error   && <div className="alert-error"   style={{ marginBottom: 12 }}>{error}</div>}
      {message && <div className="alert-success" style={{ marginBottom: 12 }}>{message}</div>}

      {/* Stats */}
      <div className="cards" style={{ padding: "0 0 20px" }}>
        <div className="card green"><h3>Present</h3><h2>{present}</h2></div>
        <div className="card red">  <h3>Absent</h3> <h2>{absent}</h2></div>
        <div className="card blue"> <h3>Total</h3>  <h2>{students.length}</h2></div>
        <div className="card">
          <h3>Percentage</h3>
          <h2>{students.length ? Math.round((present / students.length) * 100) : 0}%</h2>
        </div>
      </div>

      {/* Face Recognition */}
      <div className="section" style={{ marginBottom: 20 }}>
        <h3>Face Recognition (optional)</h3>
        <div className="camera" style={{ width: "100%", maxWidth: 500 }}>
          <div className="camera-icon">📷</div>
          {camOn ? (
            <video ref={videoRef} autoPlay playsInline style={{ width: 460, borderRadius: 8 }} />
          ) : (
            <p>Face recognition camera will appear here</p>
          )}
          {camError && <p style={{ color: "#ef4444" }}>{camError}</p>}
          <button className="start-btn" onClick={camOn ? stopCamera : startCamera}>
            {camOn ? "Stop Camera" : "Start Camera"}
          </button>
        </div>
      </div>

      {/* Bulk actions */}
      {canEdit && (
        <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap" }}>
          <button className="btn-secondary" onClick={() => markAll("present")}>Mark All Present</button>
          <button className="btn-secondary" onClick={() => markAll("absent")}>Mark All Absent</button>
        </div>
      )}

      {/* Students table */}
      {students.length === 0 ? (
        <p className="empty-state">No students enrolled in this division. Enroll students first via Admin.</p>
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>#</th><th>Roll No</th><th>Name</th><th>Face</th><th>Status</th>
                {canEdit && <th>Toggle</th>}
              </tr>
            </thead>
            <tbody>
              {students.map((s, i) => (
                <tr key={s.id}>
                  <td>{i + 1}</td>
                  <td>{s.roll_number}</td>
                  <td>{s.name}</td>
                  <td>
                    <span style={{ color: s.face_embedding ? "#16a34a" : "#aaa", fontSize: 13 }}>
                      {s.face_embedding ? "✓" : "—"}
                    </span>
                  </td>
                  <td>
                    <span className={s.status === "present" ? "present" : "absent"}>
                      {s.status === "present" ? "Present" : "Absent"}
                    </span>
                  </td>
                  {canEdit && (
                    <td>
                      <button
                        className={`btn-sm ${s.status === "present" ? "btn-danger" : "btn-edit"}`}
                        onClick={() => toggleStatus(s.id)}
                      >
                        {s.status === "present" ? "Mark Absent" : "Mark Present"}
                      </button>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Action buttons */}
      <div style={{ display: "flex", gap: 12, marginTop: 20, flexWrap: "wrap" }}>
        {canEdit && (
          <button className="btn-primary" onClick={handleSave} disabled={saving}>
            {saving ? "Saving…" : "💾 Save Attendance"}
          </button>
        )}

        {sessionId && !isLocked && (
          <button className="start-btn" onClick={handleLock} disabled={locking}>
            {locking ? "Locking…" : "🔒 Lock Attendance"}
          </button>
        )}

        {isLocked && !isEditing && (
          <button className="btn-secondary" onClick={handleUnlockForEdit}>
            ✏️ Edit Attendance
          </button>
        )}

        {isEditing && (
          <button className="btn-primary" onClick={handleSave} disabled={saving}>
            {saving ? "Saving…" : "💾 Save Changes"}
          </button>
        )}

        <button className="btn-secondary" onClick={() => { stopCamera(); navigate("/teacher"); }}>
          ← Back to Dashboard
        </button>
      </div>
    </div>
  );
}
