import React from "react";
import { NavLink, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

const ADMIN_LINKS = [
  { to: "/admin",              label: "🏠 Dashboard" },
  { to: "/admin/departments",  label: "🏛️ Departments" },
  { to: "/admin/classes",      label: "📚 Classes & Divisions" },
  { to: "/admin/subjects",     label: "📖 Subjects" },
  { to: "/admin/teachers",     label: "👨‍🏫 Teachers" },
  { to: "/admin/students",     label: "👨‍🎓 Students" },
  { to: "/admin/timetable",    label: "🗓️ Timetable" },
  { to: "/admin/settings",     label: "⚙️ Settings" },
];

const TEACHER_LINKS = [
  { to: "/teacher",             label: "🏠 Dashboard" },
  { to: "/teacher/attendance",  label: "📷 Face Attendance" },
  { to: "/teacher/history",     label: "📋 Attendance History" },
  { to: "/teacher/analytics",   label: "📊 Analytics" },
];

export default function Sidebar() {
  const { role, teacher, logout } = useAuth();
  const navigate = useNavigate();
  const links = role === "admin" ? ADMIN_LINKS : TEACHER_LINKS;

  async function handleLogout() {
    await logout();
    navigate("/login", { replace: true });
  }

  return (
    <aside className="sidebar">
      <h2>🎓 College Attendance</h2>

      {links.map(link => (
        <NavLink
          key={link.to}
          to={link.to}
          end={link.to === "/admin" || link.to === "/teacher"}
          className={({ isActive }) =>
            "sidebar-link" + (isActive ? " sidebar-link-active" : "")
          }
        >
          {link.label}
        </NavLink>
      ))}

      <div className="sidebar-footer">
        {teacher && (
          <div className="sidebar-user">
            <span className="sidebar-user-name">{teacher.name}</span>
            <span className="sidebar-user-role">Teacher</span>
          </div>
        )}
        {role === "admin" && (
          <div className="sidebar-user">
            <span className="sidebar-user-name">Administrator</span>
            <span className="sidebar-user-role">Admin</span>
          </div>
        )}
        <button className="sidebar-logout" onClick={handleLogout}>
          🚪 Logout
        </button>
      </div>
    </aside>
  );
}
