import React, { createContext, useContext, useEffect, useState } from "react";
import { supabase, IS_MOCK } from "../supabaseClient";

const AuthContext = createContext({});

export function AuthProvider({ children }) {
  const [user, setUser]       = useState(null);
  const [role, setRole]       = useState(null);   // 'admin' | 'teacher'
  const [teacher, setTeacher] = useState(null);   // teacher profile row
  const [loading, setLoading] = useState(true);

  async function loadProfile(authUser) {
    if (!authUser) {
      setUser(null); setRole(null); setTeacher(null);
      setLoading(false);
      return;
    }
    setUser(authUser);

    let userRole = null;

    if (IS_MOCK) {
      // Mock mode: get role directly from mock user list
      userRole = supabase._getMockUserRole(authUser.id);
    } else {
      // Real Supabase: query user_roles table
      const { data: roleRow } = await supabase
        .from("user_roles")
        .select("role")
        .eq("user_id", authUser.id)
        .maybeSingle();
      userRole = roleRow?.role ?? null;
    }

    setRole(userRole);

    // Load teacher profile if teacher role
    if (userRole === "teacher") {
      let teacherRow = null;
      if (IS_MOCK) {
        const teacherId = supabase._getMockTeacherId(authUser.id);
        const { data } = await supabase
          .from("teachers")
          .select("*, departments(name)")
          .eq("id", teacherId)
          .maybeSingle();
        teacherRow = data;
      } else {
        const { data } = await supabase
          .from("teachers")
          .select("*, departments(name)")
          .eq("user_id", authUser.id)
          .maybeSingle();
        teacherRow = data;
      }
      setTeacher(teacherRow);
    } else {
      setTeacher(null);
    }

    setLoading(false);
  }

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      loadProfile(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (_event, session) => {
        loadProfile(session?.user ?? null);
      }
    );
    return () => subscription.unsubscribe();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function login(email, password) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
    return data;
  }

  async function logout() {
    await supabase.auth.signOut();
    setUser(null); setRole(null); setTeacher(null);
  }

  return (
    <AuthContext.Provider value={{ user, role, teacher, loading, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
