import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "../../supabaseClient";
import { useAuth } from "../../context/AuthContext";

export default function TeacherDashboard() {
  const { teacher } = useAuth();
  const navigate    = useNavigate();

  const [todayLectures, setTodayLectures] = useState([]);
  const [assignments, setAssignments]     = useState([]);
  const [stats, setStats]                 = useState({ subjects: 0, classes: 0, totalStudents: 0 });
  const [cutoff, setCutoff]               = useState(75);
  const [lowStudents, setLowStudents]     = useState([]);
  const [loading, setLoading]             = useState(true);

  const DAYS = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
  const today = DAYS[new Date().getDay()];

  useEffect(() => {
    if (teacher?.id) fetchAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [teacher]);

  async function fetchAll() {
    setLoading(true);
    await Promise.all([fetchTodayLectures(), fetchAssignments(), fetchCutoffAndLow()]);
    setLoading(false);
  }

  async function fetchTodayLectures() {
    if (!teacher?.id) return;

    // Get today's timetable for this teacher
    const { data: ttEntries } = await supabase
      .from("timetable")
      .select(`id, start_time, end_time, room,
        subjects(id, name),
        divisions(id, name, classes(id, name))`)
      .eq("teacher_id", teacher.id)
      .eq("day_of_week", today)
      .order("start_time");

    if (!ttEntries?.length) { setTodayLectures([]); return; }

    // Check if attendance already marked for each
    const todayDate = new Date().toISOString().split("T")[0];
    const enriched = await Promise.all(ttEntries.map(async (lec) => {
      const { data: session } = await supabase
        .from("attendance_sessions")
        .select("id, is_locked")
        .eq("teacher_id", teacher.id)
        .eq("subject_id", lec.subjects.id)
        .eq("division_id", lec.divisions.id)
        .eq("date", todayDate)
        .maybeSingle();
      return { ...lec, session };
    }));

    setTodayLectures(enriched);
  }

  async function fetchAssignments() {
    if (!teacher?.id) return;
    const { data } = await supabase
      .from("teacher_assignments")
      .select("*, subjects(name), divisions(name, classes(name))")
      .eq("teacher_id", teacher.id);

    setAssignments(data || []);

    // Unique subjects and divisions
    const subjectIds = [...new Set((data || []).map(a => a.subject_id))];
    const divisionIds = [...new Set((data || []).map(a => a.division_id))];

    // Count students across assigned divisions
    let totalStudents = 0;
    for (const divId of divisionIds) {
      const { count } = await supabase
        .from("student_enrollments")
        .select("id", { count: "exact", head: true })
        .eq("division_id", divId);
      totalStudents += count || 0;
    }

    setStats({ subjects: subjectIds.length, classes: divisionIds.length, totalStudents });
  }

  async function fetchCutoffAndLow() {
    const { data } = await supabase
      .from("system_settings")
      .select("value")
      .eq("key", "attendance_cutoff")
      .maybeSingle();
    const cut = Number(data?.value || 75);
    setCutoff(cut);

    if (!teacher?.id) return;

    // Get students in this teacher's divisions
    const { data: assigns } = await supabase
      .from("teacher_assignments")
      .select("division_id")
      .eq("teacher_id", teacher.id);

    const divIds = [...new Set((assigns || []).map(a => a.division_id))];
    if (!divIds.length) return;

    const { data: enrollments } = await supabase
      .from("student_enrollments")
      .select("student_id, students(id, name, roll_number)")
      .in("division_id", divIds);

    if (!enrollments?.length) return;

    const low = [];
    for (const en of enrollments) {
      const stu = en.students;
      if (!stu) continue;
      const { data: recs } = await supabase
        .from("attendance_records")
        .select("status")
        .eq("student_id", stu.id);
      if (!recs?.length) continue;
      const total = recs.length;
      const present = recs.filter(r => r.status === "present").length;
      const pct = Math.round((present / total) * 100);
      if (pct < cut) low.push({ ...stu, pct });
    }
    low.sort((a, b) => a.pct - b.pct);
    setLowStudents(low.slice(0, 5));
  }

  function handleMarkAttendance(lecture) {
    navigate("/teacher/mark", {
      state: {
        timetableId: lecture.id,
        subjectId: lecture.subjects.id,
        subjectName: lecture.subjects.name,
        divisionId: lecture.divisions.id,
        divisionName: lecture.divisions.name,
        className: lecture.divisions.classes.name,
        startTime: lecture.start_time,
        endTime: lecture.end_time,
        sessionId: lecture.session?.id || null,
        isLocked: lecture.session?.is_locked || false,
      },
    });
  }

  if (loading) return <div className="page-loading">Loading dashboard…</div>;

  return (
    <div>
      {/* ── Teacher Info ── */}
      <div className="cards">
        <div className="card blue" style={{ gridColumn: "span 2" }}>
          <h3>Welcome back</h3>
          <h2 style={{ fontSize: 22 }}>{teacher?.name || "Teacher"}</h2>
          <p style={{ color: "#555", marginTop: 6 }}>
            {teacher?.designation} · {teacher?.departments?.name || ""}
          </p>
        </div>
        <div className="card green">
          <h3>Subjects Assigned</h3>
          <h2>{stats.subjects}</h2>
        </div>
        <div className="card">
          <h3>Classes / Divisions</h3>
          <h2>{stats.classes}</h2>
        </div>
      </div>

      {/* ── Today's Timetable ── */}
      <div className="section">
        <h2>Today's Lectures ({today})</h2>
        {todayLectures.length === 0 ? (
          <p className="empty-state">No lectures scheduled for today.</p>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Time</th><th>Subject</th><th>Class</th><th>Division</th>
                  <th>Room</th><th>Attendance</th><th>Action</th>
                </tr>
              </thead>
              <tbody>
                {todayLectures.map(lec => (
                  <tr key={lec.id}>
                    <td>{lec.start_time?.slice(0,5)} – {lec.end_time?.slice(0,5)}</td>
                    <td>{lec.subjects?.name}</td>
                    <td>{lec.divisions?.classes?.name}</td>
                    <td>{lec.divisions?.name}</td>
                    <td>{lec.room || "—"}</td>
                    <td>
                      {lec.session ? (
                        <span className={lec.session.is_locked ? "badge-locked" : "badge-open"}>
                          {lec.session.is_locked ? "🔒 Locked" : "✓ Marked"}
                        </span>
                      ) : (
                        <span className="badge-inactive">Not marked</span>
                      )}
                    </td>
                    <td>
                      <button
                        className="btn-sm btn-primary"
                        onClick={() => handleMarkAttendance(lec)}
                      >
                        {lec.session ? "View / Edit" : "Mark Attendance"}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ── Assigned Subjects ── */}
      <div className="section">
        <h2>Assigned Subjects</h2>
        {assignments.length === 0 ? (
          <p className="empty-state">No subjects assigned yet. Contact admin.</p>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr><th>#</th><th>Subject</th><th>Class</th><th>Division</th></tr>
              </thead>
              <tbody>
                {assignments.map((a, i) => (
                  <tr key={a.id}>
                    <td>{i + 1}</td>
                    <td>{a.subjects?.name}</td>
                    <td>{a.divisions?.classes?.name}</td>
                    <td>{a.divisions?.name}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ── Low Attendance Alert ── */}
      {lowStudents.length > 0 && (
        <div className="section">
          <h2>⚠️ Low Attendance Students (below {cutoff}%)</h2>
          <div className="table-wrap">
            <table>
              <thead><tr><th>Roll No</th><th>Name</th><th>Attendance</th></tr></thead>
              <tbody>
                {lowStudents.map(s => (
                  <tr key={s.id}>
                    <td>{s.roll_number}</td>
                    <td>{s.name}</td>
                    <td className="absent">{s.pct}%</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}
