import React, { useEffect, useState } from "react";
import { supabase } from "../../supabaseClient";
import { useAuth } from "../../context/AuthContext";

export default function AttendanceHistory() {
  const { teacher } = useAuth();

  const [assignments, setAssignments] = useState([]);
  const [sessions, setSessions]       = useState([]);
  const [sessionDetail, setSessionDetail] = useState(null);
  const [detailRecords, setDetailRecords] = useState([]);
  const [cutoff, setCutoff]           = useState(75);
  const [loading, setLoading]         = useState(true);
  const [detailLoading, setDetailLoading] = useState(false);

  const [filterSubject, setFilterSubject] = useState("");
  const [filterDiv, setFilterDiv]         = useState("");
  const [filterFrom, setFilterFrom]       = useState("");
  const [filterTo, setFilterTo]           = useState("");

  useEffect(() => {
    if (teacher?.id) fetchAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [teacher]);

  async function fetchAll() {
    setLoading(true);
    const [{ data: assigns }, { data: cutoffData }] = await Promise.all([
      supabase.from("teacher_assignments")
        .select("*, subjects(id, name), divisions(id, name, classes(id, name))")
        .eq("teacher_id", teacher.id),
      supabase.from("system_settings").select("value").eq("key", "attendance_cutoff").maybeSingle(),
    ]);
    setAssignments(assigns || []);
    setCutoff(Number(cutoffData?.value || 75));
    await fetchSessions(assigns || []);
    setLoading(false);
  }

  async function fetchSessions(assigns) {
    if (!assigns.length) { setSessions([]); return; }

    let query = supabase
      .from("attendance_sessions")
      .select(`id, date, is_locked, start_time,
        subjects(id, name),
        divisions(id, name, classes(name))`)
      .eq("teacher_id", teacher.id)
      .order("date", { ascending: false });

    if (filterFrom) query = query.gte("date", filterFrom);
    if (filterTo)   query = query.lte("date", filterTo);

    const { data } = await query;
    let result = data || [];

    // Attach summary counts
    const enriched = await Promise.all(result.map(async (sess) => {
      const { data: recs } = await supabase
        .from("attendance_records")
        .select("status")
        .eq("session_id", sess.id);
      const total   = recs?.length || 0;
      const present = recs?.filter(r => r.status === "present").length || 0;
      const pct     = total ? Math.round((present / total) * 100) : 0;
      return { ...sess, total, present, absent: total - present, pct };
    }));

    setSessions(enriched);
  }

  async function viewDetail(sess) {
    setDetailLoading(true);
    setSessionDetail(sess);
    const { data: recs } = await supabase
      .from("attendance_records")
      .select("status, students(id, roll_number, name)")
      .eq("session_id", sess.id)
      .order("students(roll_number)");
    setDetailRecords(recs || []);
    setDetailLoading(false);
  }

  // Subject and division unique lists from assignments
  const uniqueSubjects = [...new Map(assignments.map(a => [a.subjects.id, a.subjects])).values()];
  const uniqueDivs     = [...new Map(assignments.map(a => [a.divisions.id, a.divisions])).values()];

  const filtered = sessions.filter(s => {
    const matchSub = !filterSubject || s.subjects?.id === filterSubject;
    const matchDiv = !filterDiv     || s.divisions?.id === filterDiv;
    return matchSub && matchDiv;
  });

  if (loading) return <div className="page-loading">Loading history…</div>;

  return (
    <div>
      {/* Session detail modal */}
      {sessionDetail && (
        <div className="modal-overlay">
          <div className="modal modal-lg">
            <h3>
              {sessionDetail.subjects?.name} — {sessionDetail.divisions?.classes?.name} / Div {sessionDetail.divisions?.name}
            </h3>
            <p style={{ color: "#555", marginBottom: 12 }}>
              Date: {sessionDetail.date} &nbsp;|&nbsp;
              Present: {sessionDetail.present} &nbsp;|&nbsp;
              Absent: {sessionDetail.absent} &nbsp;|&nbsp;
              Percentage: {sessionDetail.pct}%
              {sessionDetail.is_locked && " 🔒 Locked"}
            </p>
            {detailLoading ? (
              <p>Loading…</p>
            ) : (
              <div className="table-wrap">
                <table>
                  <thead><tr><th>Roll No</th><th>Name</th><th>Status</th></tr></thead>
                  <tbody>
                    {detailRecords.map(r => (
                      <tr key={r.students?.id}>
                        <td>{r.students?.roll_number}</td>
                        <td>{r.students?.name}</td>
                        <td className={r.status === "present" ? "present" : "absent"}>
                          {r.status === "present" ? "Present" : "Absent"}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            <div className="modal-actions" style={{ marginTop: 16 }}>
              <button className="btn-secondary" onClick={() => setSessionDetail(null)}>Close</button>
            </div>
          </div>
        </div>
      )}

      <div className="section">
        <h2>Attendance History</h2>

        {/* Filters */}
        <div className="filter-bar">
          <select value={filterSubject} onChange={e => setFilterSubject(e.target.value)}>
            <option value="">All Subjects</option>
            {uniqueSubjects.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
          <select value={filterDiv} onChange={e => setFilterDiv(e.target.value)}>
            <option value="">All Divisions</option>
            {uniqueDivs.map(d => <option key={d.id} value={d.id}>{d.classes?.name} – Div {d.name}</option>)}
          </select>
          <input type="date" value={filterFrom}
            onChange={e => setFilterFrom(e.target.value)} title="From date" />
          <input type="date" value={filterTo}
            onChange={e => setFilterTo(e.target.value)} title="To date" />
          <button className="btn-primary" onClick={() => fetchSessions(assignments)}>Apply</button>
          <button className="btn-secondary" onClick={() => {
            setFilterSubject(""); setFilterDiv(""); setFilterFrom(""); setFilterTo("");
            fetchSessions(assignments);
          }}>Clear</button>
        </div>

        {filtered.length === 0 ? (
          <p className="empty-state">No attendance records found for the selected filters.</p>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Date</th><th>Subject</th><th>Class</th><th>Div</th>
                  <th>Present</th><th>Absent</th><th>%</th><th>Status</th><th>Details</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map(s => (
                  <tr key={s.id}>
                    <td>{s.date}</td>
                    <td>{s.subjects?.name}</td>
                    <td>{s.divisions?.classes?.name}</td>
                    <td>{s.divisions?.name}</td>
                    <td className="present">{s.present}</td>
                    <td className="absent">{s.absent}</td>
                    <td>
                      <span className={s.pct < cutoff ? "absent" : "present"}>
                        {s.pct}%
                      </span>
                    </td>
                    <td>
                      <span className={s.is_locked ? "badge-locked" : "badge-open"}>
                        {s.is_locked ? "🔒 Locked" : "Open"}
                      </span>
                    </td>
                    <td>
                      <button className="btn-sm btn-edit" onClick={() => viewDetail(s)}>View</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
