import React, { useEffect, useState } from "react";
import { supabase } from "../../supabaseClient";

export default function AdminDashboard() {
  const [stats, setStats] = useState({
    teachers: 0, students: 0, classes: 0, subjects: 0,
    todaySessions: 0, presentToday: 0, absentToday: 0,
  });
  const [todayLectures, setTodayLectures] = useState([]);
  const [lowAttendance, setLowAttendance] = useState([]);
  const [recentActivity, setRecentActivity] = useState([]);
  const [cutoff, setCutoff] = useState(75);
  const [loading, setLoading] = useState(true);

  const DAYS = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
  const today = DAYS[new Date().getDay()];

  useEffect(() => {
    fetchAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function fetchAll() {
    setLoading(true);
    await Promise.all([
      fetchStats(),
      fetchTodayLectures(),
      fetchCutoff(),
      fetchRecentActivity(),
    ]);
    setLoading(false);
  }

  async function fetchStats() {
    const [t, s, c, sub] = await Promise.all([
      supabase.from("teachers").select("id", { count: "exact", head: true }).eq("is_active", true),
      supabase.from("students").select("id", { count: "exact", head: true }).eq("is_active", true),
      supabase.from("divisions").select("id", { count: "exact", head: true }),
      supabase.from("subjects").select("id", { count: "exact", head: true }),
    ]);

    // today's attendance
    const todayDate = new Date().toISOString().split("T")[0];
    const { data: sessions } = await supabase
      .from("attendance_sessions")
      .select("id")
      .eq("date", todayDate);

    let present = 0, absent = 0;
    if (sessions?.length) {
      const ids = sessions.map(s => s.id);
      const { data: recs } = await supabase
        .from("attendance_records")
        .select("status")
        .in("session_id", ids);
      recs?.forEach(r => { if (r.status === "present") present++; else absent++; });
    }

    setStats({
      teachers: t.count || 0,
      students: s.count || 0,
      classes:  c.count || 0,
      subjects: sub.count || 0,
      todaySessions: sessions?.length || 0,
      presentToday: present,
      absentToday: absent,
    });
  }

  async function fetchTodayLectures() {
    const { data } = await supabase
      .from("timetable")
      .select(`
        id, start_time, end_time, room,
        subjects(name),
        teachers(name),
        divisions(name, classes(name))
      `)
      .eq("day_of_week", today)
      .order("start_time");
    setTodayLectures(data || []);
  }

  async function fetchCutoff() {
    const { data } = await supabase
      .from("system_settings")
      .select("value")
      .eq("key", "attendance_cutoff")
      .maybeSingle();
    if (data) setCutoff(Number(data.value));

    // low attendance students
    await fetchLowAttendance(Number(data?.value || 75));
  }

  async function fetchLowAttendance(cut) {
    // Get all students with their attendance %
    const { data: students } = await supabase
      .from("students")
      .select("id, name, roll_number, student_id_code")
      .eq("is_active", true);

    if (!students?.length) return;

    const results = [];
    for (const stu of students) {
      const { data: recs } = await supabase
        .from("attendance_records")
        .select("status")
        .eq("student_id", stu.id);

      if (!recs?.length) continue;
      const total = recs.length;
      const present = recs.filter(r => r.status === "present").length;
      const pct = Math.round((present / total) * 100);
      if (pct < cut) results.push({ ...stu, pct, total, present });
    }
    results.sort((a, b) => a.pct - b.pct);
    setLowAttendance(results.slice(0, 10));
  }

  async function fetchRecentActivity() {
    const { data } = await supabase
      .from("attendance_sessions")
      .select(`
        id, date, is_locked,
        subjects(name),
        teachers(name),
        divisions(name, classes(name))
      `)
      .order("created_at", { ascending: false })
      .limit(8);
    setRecentActivity(data || []);
  }

  const totalToday = stats.presentToday + stats.absentToday;
  const pctToday = totalToday ? Math.round((stats.presentToday / totalToday) * 100) : 0;

  if (loading) return <div className="page-loading">Loading dashboard…</div>;

  return (
    <div>
      {/* ── Summary Cards ── */}
      <div className="cards">
        <div className="card">
          <h3>Total Teachers</h3>
          <h2>{stats.teachers}</h2>
        </div>
        <div className="card green">
          <h3>Total Students</h3>
          <h2>{stats.students}</h2>
        </div>
        <div className="card blue">
          <h3>Classes / Divisions</h3>
          <h2>{stats.classes}</h2>
        </div>
        <div className="card">
          <h3>Total Subjects</h3>
          <h2>{stats.subjects}</h2>
        </div>
        <div className="card green">
          <h3>Present Today</h3>
          <h2>{stats.presentToday}</h2>
        </div>
        <div className="card red">
          <h3>Absent Today</h3>
          <h2>{stats.absentToday}</h2>
        </div>
        <div className="card blue">
          <h3>Today's Attendance</h3>
          <h2>{pctToday}%</h2>
        </div>
        <div className="card">
          <h3>Today's Lectures</h3>
          <h2>{stats.todaySessions}</h2>
        </div>
      </div>

      {/* ── Today's Timetable ── */}
      <div className="section">
        <h2>Today's Lectures ({today})</h2>
        {todayLectures.length === 0 ? (
          <p className="empty-state">No lectures scheduled for today.</p>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Time</th>
                  <th>Subject</th>
                  <th>Faculty</th>
                  <th>Class</th>
                  <th>Division</th>
                  <th>Room</th>
                </tr>
              </thead>
              <tbody>
                {todayLectures.map(lec => (
                  <tr key={lec.id}>
                    <td>{lec.start_time?.slice(0,5)} – {lec.end_time?.slice(0,5)}</td>
                    <td>{lec.subjects?.name}</td>
                    <td>{lec.teachers?.name}</td>
                    <td>{lec.divisions?.classes?.name}</td>
                    <td>{lec.divisions?.name}</td>
                    <td>{lec.room || "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ── Low Attendance ── */}
      {lowAttendance.length > 0 && (
        <div className="section">
          <h2>⚠️ Low Attendance Students (below {cutoff}%)</h2>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Roll No</th>
                  <th>Name</th>
                  <th>Attended</th>
                  <th>Total</th>
                  <th>Percentage</th>
                </tr>
              </thead>
              <tbody>
                {lowAttendance.map(s => (
                  <tr key={s.id}>
                    <td>{s.student_id_code}</td>
                    <td>{s.roll_number}</td>
                    <td>{s.name}</td>
                    <td>{s.present}</td>
                    <td>{s.total}</td>
                    <td className="absent">{s.pct}%</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ── Recent Activity ── */}
      <div className="section">
        <h2>Recent Attendance Activity</h2>
        {recentActivity.length === 0 ? (
          <p className="empty-state">No attendance recorded yet.</p>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Subject</th>
                  <th>Teacher</th>
                  <th>Class</th>
                  <th>Division</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {recentActivity.map(s => (
                  <tr key={s.id}>
                    <td>{s.date}</td>
                    <td>{s.subjects?.name}</td>
                    <td>{s.teachers?.name}</td>
                    <td>{s.divisions?.classes?.name}</td>
                    <td>{s.divisions?.name}</td>
                    <td>
                      <span className={s.is_locked ? "badge-locked" : "badge-open"}>
                        {s.is_locked ? "Locked" : "Open"}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
