import React, { useEffect, useState } from "react";
import { supabase } from "../../supabaseClient";

export default function StudentManagement() {
  const [students, setStudents]       = useState([]);
  const [departments, setDepartments] = useState([]);
  const [divisions, setDivisions]     = useState([]);
  const [loading, setLoading]         = useState(true);
  const [saving, setSaving]           = useState(false);
  const [error, setError]             = useState("");

  const [search, setSearch]           = useState("");
  const [filterDiv, setFilterDiv]     = useState("");
  const [filterDept, setFilterDept]   = useState("");

  // Student form
  const [showForm, setShowForm]       = useState(false);
  const [editId, setEditId]           = useState(null);
  const [form, setForm]               = useState({
    name: "", roll_number: "", student_id_code: "", email: "",
    department_id: "", division_id: "",
  });

  useEffect(() => { fetchAll(); }, []);

  async function fetchAll() {
    setLoading(true);
    const [{ data: studs }, { data: depts }, { data: divs }] = await Promise.all([
      supabase.from("students")
        .select(`*, departments(name),
          student_enrollments(division_id, divisions(name, classes(name)))`)
        .eq("is_active", true)
        .order("roll_number"),
      supabase.from("departments").select("*").order("name"),
      supabase.from("divisions").select("*, classes(name)").order("name"),
    ]);
    setStudents(studs || []);
    setDepartments(depts || []);
    setDivisions(divs || []);
    setLoading(false);
  }

  function openAdd() {
    setForm({ name: "", roll_number: "", student_id_code: "", email: "", department_id: "", division_id: "" });
    setEditId(null); setError(""); setShowForm(true);
  }
  function openEdit(s) {
    const enrollment = s.student_enrollments?.[0];
    setForm({
      name: s.name, roll_number: s.roll_number, student_id_code: s.student_id_code,
      email: s.email || "", department_id: s.department_id || "",
      division_id: enrollment?.division_id || "",
    });
    setEditId(s.id); setError(""); setShowForm(true);
  }

  async function handleSave(e) {
    e.preventDefault();
    if (!form.name.trim() || !form.roll_number.trim() || !form.student_id_code.trim()) {
      setError("Name, roll number and student ID required."); return;
    }
    setSaving(true); setError("");
    try {
      const stuPayload = {
        name: form.name.trim(),
        roll_number: form.roll_number.trim(),
        student_id_code: form.student_id_code.trim(),
        email: form.email.trim() || null,
        department_id: form.department_id || null,
      };

      let studentId = editId;

      if (editId) {
        const { error: err } = await supabase.from("students").update(stuPayload).eq("id", editId);
        if (err) throw err;
      } else {
        const { data, error: err } = await supabase.from("students").insert(stuPayload).select().single();
        if (err) throw err;
        studentId = data.id;
      }

      // Handle enrollment
      if (form.division_id) {
        // Delete old enrollment for this student and insert new
        await supabase.from("student_enrollments").delete().eq("student_id", studentId);
        const { error: enErr } = await supabase.from("student_enrollments").insert({
          student_id: studentId,
          division_id: form.division_id,
          academic_year: "2026-27",
        });
        if (enErr) throw enErr;
      }

      setShowForm(false); fetchAll();
    } catch (err) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  }

  async function toggleActive(student) {
    if (!window.confirm(`Deactivate student "${student.name}"?`)) return;
    await supabase.from("students").update({ is_active: false }).eq("id", student.id);
    fetchAll();
  }

  // Filter
  const filtered = students.filter(s => {
    const enrollment = s.student_enrollments?.[0];
    const matchSearch = !search ||
      s.name.toLowerCase().includes(search.toLowerCase()) ||
      s.roll_number.includes(search) ||
      s.student_id_code.toLowerCase().includes(search.toLowerCase());
    const matchDiv = !filterDiv || enrollment?.division_id === filterDiv;
    const matchDept = !filterDept || s.department_id === filterDept;
    return matchSearch && matchDiv && matchDept;
  });

  if (loading) return <div className="page-loading">Loading…</div>;

  return (
    <div className="section">
      <div className="section-header">
        <h2>Students</h2>
        <button className="btn-primary" onClick={openAdd}>+ Add Student</button>
      </div>

      {/* Filters */}
      <div className="filter-bar">
        <input className="search" placeholder="Search by name, roll no, ID…"
          value={search} onChange={e => setSearch(e.target.value)} />
        <select value={filterDiv} onChange={e => setFilterDiv(e.target.value)}>
          <option value="">All Divisions</option>
          {divisions.map(d => <option key={d.id} value={d.id}>{d.classes?.name} – Div {d.name}</option>)}
        </select>
        <select value={filterDept} onChange={e => setFilterDept(e.target.value)}>
          <option value="">All Departments</option>
          {departments.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
        </select>
        <button className="btn-secondary" onClick={() => { setSearch(""); setFilterDiv(""); setFilterDept(""); }}>
          Clear
        </button>
      </div>

      {/* Form Modal */}
      {showForm && (
        <div className="modal-overlay">
          <div className="modal modal-lg">
            <h3>{editId ? "Edit Student" : "Add Student"}</h3>
            {error && <div className="alert-error">{error}</div>}
            <form onSubmit={handleSave} className="modal-form">
              <div className="form-row">
                <div className="form-group">
                  <label>Student ID Code</label>
                  <input placeholder="e.g. STU001" value={form.student_id_code}
                    onChange={e => setForm(f => ({ ...f, student_id_code: e.target.value }))} required />
                </div>
                <div className="form-group">
                  <label>Roll Number</label>
                  <input placeholder="e.g. 23" value={form.roll_number}
                    onChange={e => setForm(f => ({ ...f, roll_number: e.target.value }))} required />
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Full Name</label>
                  <input placeholder="Student name" value={form.name}
                    onChange={e => setForm(f => ({ ...f, name: e.target.value }))} required />
                </div>
                <div className="form-group">
                  <label>Email (optional)</label>
                  <input type="email" placeholder="student@college.edu" value={form.email}
                    onChange={e => setForm(f => ({ ...f, email: e.target.value }))} />
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Department</label>
                  <select value={form.department_id} onChange={e => setForm(f => ({ ...f, department_id: e.target.value }))}>
                    <option value="">None</option>
                    {departments.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>Enroll in Division</label>
                  <select value={form.division_id} onChange={e => setForm(f => ({ ...f, division_id: e.target.value }))}>
                    <option value="">Not enrolled</option>
                    {divisions.map(d => <option key={d.id} value={d.id}>{d.classes?.name} – Div {d.name}</option>)}
                  </select>
                </div>
              </div>
              <div className="modal-actions">
                <button type="button" className="btn-secondary" onClick={() => setShowForm(false)}>Cancel</button>
                <button type="submit" className="btn-primary" disabled={saving}>{saving ? "Saving…" : "Save"}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Table */}
      <p style={{ color: "#666", marginBottom: 12 }}>Showing {filtered.length} of {students.length} students</p>
      {filtered.length === 0 ? (
        <p className="empty-state">No students match the current filters.</p>
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>ID</th><th>Roll No</th><th>Name</th><th>Class</th>
                <th>Division</th><th>Department</th><th>Embedding</th><th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(s => {
                const enrollment = s.student_enrollments?.[0];
                return (
                  <tr key={s.id}>
                    <td>{s.student_id_code}</td>
                    <td>{s.roll_number}</td>
                    <td>{s.name}</td>
                    <td>{enrollment?.divisions?.classes?.name || "—"}</td>
                    <td>{enrollment?.divisions?.name || "—"}</td>
                    <td>{s.departments?.name || "—"}</td>
                    <td>
                      <span className={s.face_embedding ? "badge-active" : "badge-inactive"}>
                        {s.face_embedding ? "✓ Set" : "Not set"}
                      </span>
                    </td>
                    <td>
                      <button className="btn-sm btn-edit" onClick={() => openEdit(s)}>Edit</button>
                      <button className="btn-sm btn-danger" onClick={() => toggleActive(s)}>Deactivate</button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
