import React, { useEffect, useState } from "react";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line, Legend,
} from "recharts";
import { supabase } from "../../supabaseClient";
import { useAuth } from "../../context/AuthContext";

export default function Analytics() {
  const { teacher } = useAuth();

  const [subjectStats, setSubjectStats]   = useState([]);
  const [trendData, setTrendData]         = useState([]);
  const [studentData, setStudentData]     = useState([]);
  const [cutoff, setCutoff]               = useState(75);
  const [loading, setLoading]             = useState(true);
  const [overallStats, setOverallStats]   = useState({ total: 0, present: 0, absent: 0, pct: 0 });
  const [filterView, setFilterView]       = useState("all"); // all | low

  useEffect(() => {
    if (teacher?.id) fetchAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [teacher]);

  async function fetchAll() {
    setLoading(true);
    const { data: cutoffData } = await supabase
      .from("system_settings").select("value").eq("key", "attendance_cutoff").maybeSingle();
    const cut = Number(cutoffData?.value || 75);
    setCutoff(cut);

    // All sessions for this teacher
    const { data: sessions } = await supabase
      .from("attendance_sessions")
      .select(`id, date,
        subjects(id, name),
        divisions(id, name, classes(name))`)
      .eq("teacher_id", teacher.id)
      .order("date");

    if (!sessions?.length) {
      setLoading(false); return;
    }

    // All records for all sessions
    const sessionIds = sessions.map(s => s.id);
    const { data: records } = await supabase
      .from("attendance_records")
      .select("session_id, student_id, status, students(id, name, roll_number)")
      .in("session_id", sessionIds);

    // ── Subject-wise stats ──
    const subjectMap = {};
    sessions.forEach(sess => {
      const sid  = sess.subjects?.id;
      const sname = sess.subjects?.name;
      if (!sid) return;
      if (!subjectMap[sid]) subjectMap[sid] = { name: sname, total: 0, present: 0 };
      const sessRecs = (records || []).filter(r => r.session_id === sess.id);
      subjectMap[sid].total   += sessRecs.length;
      subjectMap[sid].present += sessRecs.filter(r => r.status === "present").length;
    });
    const subStats = Object.values(subjectMap).map(s => ({
      name: s.name,
      avg: s.total ? Math.round((s.present / s.total) * 100) : 0,
      total: s.total, present: s.present,
    }));
    setSubjectStats(subStats);

    // ── Overall ──
    const allRecs = records || [];
    const totalRecs = allRecs.length;
    const totalPresent = allRecs.filter(r => r.status === "present").length;
    setOverallStats({
      total: totalRecs,
      present: totalPresent,
      absent: totalRecs - totalPresent,
      pct: totalRecs ? Math.round((totalPresent / totalRecs) * 100) : 0,
    });

    // ── Trend (last 30 days) ──
    const last30 = sessions.slice(-30);
    const trendMap = {};
    last30.forEach(sess => {
      const date = sess.date;
      if (!trendMap[date]) trendMap[date] = { date, present: 0, absent: 0 };
      const sessRecs = (records || []).filter(r => r.session_id === sess.id);
      sessRecs.forEach(r => {
        if (r.status === "present") trendMap[date].present++;
        else trendMap[date].absent++;
      });
    });
    setTrendData(Object.values(trendMap));

    // ── Student-wise ──
    const stuMap = {};
    (records || []).forEach(r => {
      const stu = r.students;
      if (!stu) return;
      if (!stuMap[stu.id]) stuMap[stu.id] = { ...stu, total: 0, present: 0 };
      stuMap[stu.id].total++;
      if (r.status === "present") stuMap[stu.id].present++;
    });
    const stuList = Object.values(stuMap).map(s => ({
      ...s,
      pct: s.total ? Math.round((s.present / s.total) * 100) : 0,
    }));
    stuList.sort((a, b) => a.pct - b.pct);
    setStudentData(stuList);

    setLoading(false);
  }

  const displayedStudents = filterView === "low"
    ? studentData.filter(s => s.pct < cutoff)
    : studentData;

  if (loading) return <div className="page-loading">Loading analytics…</div>;

  return (
    <div>
      {/* ── Overall cards ── */}
      <div className="cards">
        <div className="card">     <h3>Total Records</h3>     <h2>{overallStats.total}</h2></div>
        <div className="card green"><h3>Total Present</h3>    <h2>{overallStats.present}</h2></div>
        <div className="card red">  <h3>Total Absent</h3>     <h2>{overallStats.absent}</h2></div>
        <div className="card blue"> <h3>Overall Percentage</h3><h2>{overallStats.pct}%</h2></div>
      </div>

      {/* ── Subject-wise bar chart ── */}
      <div className="section">
        <h2>Subject-wise Average Attendance</h2>
        {subjectStats.length === 0 ? (
          <p className="empty-state">No data yet.</p>
        ) : (
          <>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={subjectStats} margin={{ top: 10, right: 30, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis domain={[0, 100]} unit="%" />
                <Tooltip formatter={(v) => `${v}%`} />
                <Bar dataKey="avg" fill="#2563eb" name="Avg Attendance %" radius={[4,4,0,0]} />
              </BarChart>
            </ResponsiveContainer>
            {/* Subject summary */}
            <div className="report" style={{ marginTop: 20 }}>
              {subjectStats.map(s => (
                <div key={s.name}>
                  <h3>{s.name}</h3>
                  <strong style={{ color: s.avg < cutoff ? "#dc2626" : "#2563eb" }}>
                    {s.avg}%
                  </strong>
                  <p style={{ fontSize: 12, color: "#666", marginTop: 4 }}>
                    {s.present}/{s.total} present
                  </p>
                </div>
              ))}
            </div>
          </>
        )}
      </div>

      {/* ── Attendance trend ── */}
      <div className="section">
        <h2>Attendance Trend (last 30 days)</h2>
        {trendData.length === 0 ? (
          <p className="empty-state">No data yet.</p>
        ) : (
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={trendData} margin={{ top: 10, right: 30, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" tick={{ fontSize: 11 }} />
              <YAxis />
              <Tooltip />
              <Legend />
              <Line type="monotone" dataKey="present" stroke="#22c55e" name="Present" strokeWidth={2} dot={false} />
              <Line type="monotone" dataKey="absent"  stroke="#ef4444" name="Absent"  strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        )}
      </div>

      {/* ── Student-wise ── */}
      <div className="section">
        <div className="section-header">
          <h2>Student Attendance</h2>
          <div style={{ display: "flex", gap: 8 }}>
            <button
              className={filterView === "all" ? "btn-primary btn-sm" : "btn-secondary btn-sm"}
              onClick={() => setFilterView("all")}
            >All Students</button>
            <button
              className={filterView === "low" ? "btn-primary btn-sm" : "btn-secondary btn-sm"}
              onClick={() => setFilterView("low")}
            >⚠️ Below {cutoff}%</button>
          </div>
        </div>

        {displayedStudents.length === 0 ? (
          <p className="empty-state">
            {filterView === "low" ? `No students below ${cutoff}%.` : "No student data yet."}
          </p>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr><th>Roll No</th><th>Name</th><th>Present</th><th>Total</th><th>%</th><th>Status</th></tr>
              </thead>
              <tbody>
                {displayedStudents.map(s => (
                  <tr key={s.id}>
                    <td>{s.roll_number}</td>
                    <td>{s.name}</td>
                    <td>{s.present}</td>
                    <td>{s.total}</td>
                    <td className={s.pct < cutoff ? "absent" : "present"}>{s.pct}%</td>
                    <td>
                      {s.pct < cutoff
                        ? <span className="badge-inactive">⚠️ Low</span>
                        : <span className="badge-active">✓ OK</span>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
