import React, { useEffect, useState } from "react";
import { supabase } from "../../supabaseClient";

const DAYS = ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];

export default function TimetableManagement() {
  const [entries, setEntries]   = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [divisions, setDivisions] = useState([]);
  const [loading, setLoading]   = useState(true);
  const [saving, setSaving]     = useState(false);
  const [error, setError]       = useState("");
  const [showForm, setShowForm] = useState(false);
  const [editId, setEditId]     = useState(null);
  const [filterDay, setFilterDay] = useState("");

  const [form, setForm] = useState({
    day_of_week: "Monday", start_time: "", end_time: "",
    subject_id: "", teacher_id: "", division_id: "", room: "",
  });

  useEffect(() => { fetchAll(); }, []);

  async function fetchAll() {
    setLoading(true);
    const [{ data: ent }, { data: sub }, { data: tea }, { data: div }] = await Promise.all([
      supabase.from("timetable")
        .select(`*, subjects(name), teachers(name), divisions(name, classes(name))`)
        .order("day_of_week").order("start_time"),
      supabase.from("subjects").select("*").order("name"),
      supabase.from("teachers").select("*").eq("is_active", true).order("name"),
      supabase.from("divisions").select("*, classes(name)").order("name"),
    ]);
    setEntries(ent || []);
    setSubjects(sub || []);
    setTeachers(tea || []);
    setDivisions(div || []);
    setLoading(false);
  }

  function openAdd() {
    setForm({ day_of_week: "Monday", start_time: "", end_time: "", subject_id: "", teacher_id: "", division_id: "", room: "" });
    setEditId(null); setError(""); setShowForm(true);
  }
  function openEdit(e) {
    setForm({
      day_of_week: e.day_of_week,
      start_time: e.start_time?.slice(0,5) || "",
      end_time: e.end_time?.slice(0,5) || "",
      subject_id: e.subject_id,
      teacher_id: e.teacher_id,
      division_id: e.division_id,
      room: e.room || "",
    });
    setEditId(e.id); setError(""); setShowForm(true);
  }

  async function handleSave(ev) {
    ev.preventDefault();
    if (!form.start_time || !form.end_time || !form.subject_id || !form.teacher_id || !form.division_id) {
      setError("All fields except room are required."); return;
    }
    setSaving(true); setError("");
    const payload = {
      day_of_week: form.day_of_week,
      start_time: form.start_time,
      end_time: form.end_time,
      subject_id: form.subject_id,
      teacher_id: form.teacher_id,
      division_id: form.division_id,
      room: form.room || null,
    };
    let err;
    if (editId) {
      ({ error: err } = await supabase.from("timetable").update(payload).eq("id", editId));
    } else {
      ({ error: err } = await supabase.from("timetable").insert(payload));
    }
    setSaving(false);
    if (err) { setError(err.message); return; }
    setShowForm(false); fetchAll();
  }

  async function handleDelete(id) {
    if (!window.confirm("Delete this timetable entry?")) return;
    await supabase.from("timetable").delete().eq("id", id);
    fetchAll();
  }

  const displayed = filterDay ? entries.filter(e => e.day_of_week === filterDay) : entries;

  if (loading) return <div className="page-loading">Loading…</div>;

  return (
    <div className="section">
      <div className="section-header">
        <h2>Weekly Timetable</h2>
        <button className="btn-primary" onClick={openAdd}>+ Add Entry</button>
      </div>

      {/* Day filter */}
      <div className="filter-bar">
        <select value={filterDay} onChange={e => setFilterDay(e.target.value)}>
          <option value="">All Days</option>
          {DAYS.map(d => <option key={d} value={d}>{d}</option>)}
        </select>
      </div>

      {/* Form Modal */}
      {showForm && (
        <div className="modal-overlay">
          <div className="modal modal-lg">
            <h3>{editId ? "Edit Entry" : "Add Timetable Entry"}</h3>
            {error && <div className="alert-error">{error}</div>}
            <form onSubmit={handleSave} className="modal-form">
              <div className="form-row">
                <div className="form-group">
                  <label>Day</label>
                  <select value={form.day_of_week} onChange={e => setForm(f => ({ ...f, day_of_week: e.target.value }))}>
                    {DAYS.map(d => <option key={d} value={d}>{d}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>Start Time</label>
                  <input type="time" value={form.start_time}
                    onChange={e => setForm(f => ({ ...f, start_time: e.target.value }))} required />
                </div>
                <div className="form-group">
                  <label>End Time</label>
                  <input type="time" value={form.end_time}
                    onChange={e => setForm(f => ({ ...f, end_time: e.target.value }))} required />
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Subject</label>
                  <select value={form.subject_id} onChange={e => setForm(f => ({ ...f, subject_id: e.target.value }))} required>
                    <option value="">Select Subject</option>
                    {subjects.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>Teacher</label>
                  <select value={form.teacher_id} onChange={e => setForm(f => ({ ...f, teacher_id: e.target.value }))} required>
                    <option value="">Select Teacher</option>
                    {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                  </select>
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Division</label>
                  <select value={form.division_id} onChange={e => setForm(f => ({ ...f, division_id: e.target.value }))} required>
                    <option value="">Select Division</option>
                    {divisions.map(d => <option key={d.id} value={d.id}>{d.classes?.name} – Div {d.name}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>Room (optional)</label>
                  <input placeholder="e.g. A-201" value={form.room}
                    onChange={e => setForm(f => ({ ...f, room: e.target.value }))} />
                </div>
              </div>
              <div className="modal-actions">
                <button type="button" className="btn-secondary" onClick={() => setShowForm(false)}>Cancel</button>
                <button type="submit" className="btn-primary" disabled={saving}>{saving ? "Saving…" : "Save"}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Timetable grouped by day */}
      {DAYS.filter(d => !filterDay || d === filterDay).map(day => {
        const dayEntries = displayed.filter(e => e.day_of_week === day);
        if (!filterDay && dayEntries.length === 0) return null;
        return (
          <div key={day} style={{ marginBottom: 24 }}>
            <h3 style={{ marginBottom: 8, color: "#172554" }}>{day}</h3>
            {dayEntries.length === 0 ? (
              <p className="empty-state" style={{ marginLeft: 0 }}>No lectures on {day}.</p>
            ) : (
              <div className="table-wrap">
                <table>
                  <thead>
                    <tr><th>Time</th><th>Subject</th><th>Teacher</th><th>Class</th><th>Div</th><th>Room</th><th>Actions</th></tr>
                  </thead>
                  <tbody>
                    {dayEntries.map(e => (
                      <tr key={e.id}>
                        <td>{e.start_time?.slice(0,5)} – {e.end_time?.slice(0,5)}</td>
                        <td>{e.subjects?.name}</td>
                        <td>{e.teachers?.name}</td>
                        <td>{e.divisions?.classes?.name}</td>
                        <td>{e.divisions?.name}</td>
                        <td>{e.room || "—"}</td>
                        <td>
                          <button className="btn-sm btn-edit" onClick={() => openEdit(e)}>Edit</button>
                          <button className="btn-sm btn-danger" onClick={() => handleDelete(e.id)}>Delete</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        );
      })}

      {displayed.length === 0 && (
        <p className="empty-state">No timetable entries yet. Add one to get started.</p>
      )}
    </div>
  );
}
