import React from "react";
import { Outlet, useLocation } from "react-router-dom";
import Sidebar from "./Sidebar";
import { useAuth } from "../context/AuthContext";

// Map pathname to a readable title
function getTitle(pathname) {
  const map = {
    "/admin":               "Dashboard",
    "/admin/departments":   "Departments",
    "/admin/classes":       "Classes & Divisions",
    "/admin/subjects":      "Subjects",
    "/admin/teachers":      "Teacher Management",
    "/admin/students":      "Student Management",
    "/admin/timetable":     "Timetable",
    "/admin/settings":      "Attendance Settings",
    "/teacher":             "Dashboard",
    "/teacher/attendance":  "Face Attendance",
    "/teacher/history":     "Attendance History",
    "/teacher/analytics":   "Analytics",
    "/teacher/mark":        "Mark Attendance",
  };
  return map[pathname] || "Attendance System";
}

export default function Layout() {
  const { role, teacher } = useAuth();
  const location = useLocation();
  const title = getTitle(location.pathname);

  const displayName = role === "admin" ? "Admin" : (teacher?.name || "Teacher");

  return (
    <div className="app">
      <Sidebar />
      <main className="main">
        <header>
          <h1>{title}</h1>
          <span>{displayName} ({role})</span>
        </header>
        <Outlet />
      </main>
    </div>
  );
}
